// ===== НАПОМИНАНИЯ: ЗА 2 ДНЯ + ЗА 1 ЧАС ДО ПАРЫ =====
async function checkReminders() {
  const tasks = loadTasks();
  const now = new Date();
  let changed = false;

  for (const task of tasks) {
    if (task.done) continue;
    const deadline = new Date(task.deadline);
    const diff = deadline - now;

    // 1. Напоминание за 2 дня до дедлайна
    if (!task.reminded && diff > 0 && diff <= 2 * 24 * 60 * 60 * 1000 && diff >= (2 * 24 * 60 - 30) * 60 * 1000) {
      try {
        const daysLeft = Math.ceil(diff / (24 * 60 * 60 * 1000));
        const timeStr = deadline.toLocaleString("ru-RU", { day: "numeric", month: "long", hour: "2-digit", minute: "2-digit" });
        await bot.telegram.sendMessage(task.userId, `🔔 *Напоминание\\!*\n\n📝 ${task.title.replace(/[\\_*\\[\\]()~\`>#+=|{}.!-]/g, "\\$&")}\n📅 Дедлайн: ${timeStr}\n⏰ Осталось: ${daysLeft} дн\\.`, { parse_mode: "MarkdownV2" });
        task.reminded = true;
        changed = true;
      } catch (e) { console.log("Не удалось отправить напоминание за 2 дня", task.userId, e.message); }
    }

    // 2. Автоотправка готового ДЗ в чат за 1 час до пары
    // Проверяем задачи, у которых дедлайн в пределах следующего часа
    if (!task.sentToChat && diff > 0 && diff <= 60 * 60 * 1000 && diff >= 30 * 60 * 1000) {
      try {
        const timeStr = deadline.toLocaleString("ru-RU", { day: "numeric", month: "long", hour: "2-digit", minute: "2-digit" });
        await bot.telegram.sendMessage(
          task.userId,
          `📝 *Домашнее задание к паре\\!*\n\n📌 ${task.title.replace(/[\\_*\\[\\]()~\`>#+=|{}.!-]/g, "\\$&")}\n⏰ Пара начинается: ${timeStr}\n\n💡 _Открой расписание и нажми 🤖 у нужной пары, чтобы решить через ИИ_`,
          { parse_mode: "MarkdownV2" }
        );
        task.sentToChat = true;
        changed = true;
      } catch (e) { console.log("Не удалось отправить ДЗ в чат", task.userId, e.message); }
    }
  }
  if (changed) saveTasks(tasks);
}

cron.schedule("*/5 * * * *", checkReminders);
setTimeout(checkReminders, 15000);

